#include <bits/stdc++.h>
using namespace std;
#define ll long long

int main() {
	// your code goes here
	int t;
	cin>>t;
	while(t--){
	    ll n;
	    cin>>n;
	    ll total = 3*n;
	    
	    vector<ll>a(total+1);
	    
	    for(ll i= 1;i<=total;i++){
	        cin>>a[i];
	    }
	    
	    sort(a.begin()+1,a.end(),greater<ll>());
	    
	    vector<ll>p(total+1,0);
	    
	    for(int i=1;i<=total;i++){
	        p[i] = p[i-1] + a[i];
	    }
	    
	    ll mx = -1;
	    
	    for(int k=0;k<=2*n;k++){
	        ll left = max(0LL,k-n);
	        ll right = k>>1;
	        ll bestFroma = left;
	        ll srcLeft = left;
	        ll srcRight = right-1;
	        
	        while(srcLeft<=srcRight){
	            ll mid = srcLeft+((srcRight-srcLeft)>>1);
	            
	            ll diff = 2*a[mid+1] - a[2*k-3*mid] -a[2*k-3*mid-1] - a[2*k-3*mid-2];
	            
	            if(diff>=0){
	                bestFroma = mid+1;
	                srcLeft = mid+1;
	            }else{
	                srcRight = mid-1;
	            }
	        }
	        
	        int X = max(left,bestFroma-2);
	        int Y = min(right,bestFroma+2);
	        
	        for(ll j = X; j<=Y; j++){
	            ll curr = 2*p[j] + p[2*k-3*j] + 3*p[3*n-k];
	            
	            mx = max(mx,curr);
	        }
	    }
	    cout<<mx<<endl;
	}

}
